@interface AppDelegate:NSObject<NSApplicationDelegate>
@property NSStatusItem*statusItem;@property NSPopover*popover;@property QuotaVC*quotaVC;@property NSTask*task;@property NSPipe*inputPipe;@property NSMutableData*buffer;@property NSTimer*timer;@property NSInteger nextID;
