@implementation AppDelegate
- (void)applicationDidFinishLaunching:(NSNotification*)n{self.nextID=10;self.buffer=[NSMutableData data];self.statusItem=[NSStatusBar.systemStatusBar statusItemWithLength:NSVariableStatusItemLength];NSStatusBarButton*b=self.statusItem.button;b.title=@"—";b.image=[NSImage imageWithSystemSymbolName:@"gauge.with.dots.needle.33percent" accessibilityDescription:@"Codex 限额"];b.imagePosition=NSImageLeading;if([b respondsToSelector:@selector(setImageHugsTitle:)])b.imageHugsTitle=YES;b.target=self;b.action=@selector(toggle:);self.quotaVC=[QuotaVC new];[self.quotaVC loadView];self.quotaVC.refreshButton.target=self;self.quotaVC.refreshButton.action=@selector(refresh:);self.quotaVC.loginButton=[NSButton checkboxWithTitle:@"登录时自动启动" target:self action:@selector(toggleLogin:)];self.quotaVC.loginButton.controlSize=NSControlSizeSmall;self.quotaVC.loginButton.state=SMAppService.mainAppService.status==SMAppServiceStatusEnabled?NSControlStateValueOn:NSControlStateValueOff;self.quotaVC.loginButton.translatesAutoresizingMaskIntoConstraints=NO;[self.quotaVC.view addSubview:self.quotaVC.loginButton];[NSLayoutConstraint activateConstraints:@[[self.quotaVC.loginButton.centerXAnchor constraintEqualToAnchor:self.quotaVC.view.centerXAnchor],[self.quotaVC.loginButton.bottomAnchor constraintEqualToAnchor:self.quotaVC.view.bottomAnchor constant:-35]]];self.popover=[NSPopover new];self.popover.contentViewController=self.quotaVC;self.popover.behavior=NSPopoverBehaviorTransient;self.popover.animates=YES;[self startService];self.timer=[NSTimer scheduledTimerWithTimeInterval:1800 target:self selector:@selector(refresh:) userInfo:nil repeats:YES];}
