- (void)toggle:(id)s{if(self.popover.shown)[self.popover close];else{[self.popover showRelativeToRect:self.statusItem.button.bounds ofView:self.statusItem.button preferredEdge:NSRectEdgeMinY];[self refresh:nil];}}
- (NSString*)codexPath{for(NSString*p in @[@"/Applications/ChatGPT.app/Contents/Resources/codex",@"/Applications/Codex.app/Contents/Resources/codex"])if([NSFileManager.defaultManager isExecutableFileAtPath:p])return p;return nil;}
- (void)startService{NSString*p=[self codexPath];if(!p){[self error:@"未找到 ChatGPT/Codex"];return;}self.task=[NSTask new];self.task.executableURL=[NSURL fileURLWithPath:p];self.task.arguments=@[@"app-server"];self.inputPipe=[NSPipe pipe];NSPipe*out=[NSPipe pipe];self.task.standardInput=self.inputPipe;self.task.standardOutput=out;self.task.standardError=[NSPipe pipe];__weak typeof(self)w=self;out.fileHandleForReading.readabilityHandler=^(NSFileHandle*h){NSData*d=h.availableData;if(d.length)dispatch_async(dispatch_get_main_queue(),^{[w consume:d];});};NSError*e;if(![self.task launchAndReturnError:&e]){[self error:e.localizedDescription];return;}[self send:@{@"method":@"initialize",@"id":@1,@"params":@{@"clientInfo":@{@"name":@"CodexQuota",@"version":@"1.1"},@"capabilities":@{}}}];dispatch_after(dispatch_time(DISPATCH_TIME_NOW,400000000),dispatch_get_main_queue(),^{[self send:@{@"method":@"initialized",@"params":@{}}];[self refresh:nil];});}
