- (void)consume:(NSData*)d{[self.buffer appendData:d];while(1){const unsigned char*b=self.buffer.bytes;NSUInteger n=self.buffer.length,i=NSNotFound;for(NSUInteger x=0;x<n;x++)if(b[x]=='\n'){i=x;break;}if(i==NSNotFound)break;NSData*l=[self.buffer subdataWithRange:NSMakeRange(0,i)];[self.buffer replaceBytesInRange:NSMakeRange(0,i+1) withBytes:NULL length:0];NSDictionary*j=l.length?[NSJSONSerialization JSONObjectWithData:l options:0 error:nil]:nil;NSDictionary*r=[j[@"result"] isKindOfClass:NSDictionary.class]?j[@"result"]:nil;if(r[@"rateLimits"])[self applyLimits:r];if(r[@"summary"])[self applyUsage:r];}}
